+  if (JSON.stringify([...(question.source_membership ?? [])].sort()) !== JSON.stringify(expectedSourceIds.sort())) errors.push('source_membership');
+  return errors;
+}
+
+export function validateVerificationRecord(verification, sourceRecords, evidenceManifest) {
+  const errors = [];
+  const extractions = [['maker', verification.maker], ['checker', verification.checker]].filter(([, value]) => value !== null && value !== undefined);
+  for (const [role, extraction] of extractions) {
+    if (extraction.question_id !== verification.question_id) errors.push(`${role}.question_id`);
+    if (extraction.question?.question_id !== verification.question_id) errors.push(`${role}.question.question_id`);
+    for (const field of validateQuestionIdentity(extraction.question ?? {})) errors.push(`${role}.question.${field}`);
+    for (const field of validateExtractionOutput(extraction, sourceRecords, evidenceManifest)) errors.push(`${role}.extraction.${field}`);
+  }
+  const disagreeingFields = verification.comparison?.disagreeing_fields ?? [];
+  const comparedFields = new Set(verification.comparison?.compared_fields ?? []);
+  if (verification.comparison?.equivalent === true && disagreeingFields.length > 0) errors.push('comparison.disagreeing_fields');
+  if (verification.comparison?.equivalent === false && disagreeingFields.length === 0) errors.push('comparison.disagreeing_fields');
+  if (disagreeingFields.some((field) => !comparedFields.has(field))) errors.push('comparison.disagreeing_fields_not_compared');
+  if (verification.resolver) {
+    const decisionFields = verification.resolver.field_decisions?.map((row) => row.field) ?? [];
+    const exactDecisionSet = unique(decisionFields)
+      && JSON.stringify([...decisionFields].sort()) === JSON.stringify([...disagreeingFields].sort());
+    if (!exactDecisionSet) errors.push('resolver.field_decisions');
+  }
+  const actors = [verification.maker?.provenance, verification.checker?.provenance, verification.resolver?.provenance].filter(Boolean);
+  for (const field of ['worker_id', 'raw_response_sha256', 'record_sha256']) {
+    if (!unique(actors.map((actor) => actor[field]))) errors.push(`actor_independence.${field}`);
+  }
+  return errors;
+}
+
+export function validateExtractionOutput(extraction, sourceRecords, evidenceManifest) {
+  const errors = [];
+  if (extraction.question_id !== extraction.question?.question_id) errors.push('question_id');
+  for (const field of validateQuestionIdentity(extraction.question ?? {})) errors.push(`question.${field}`);
+  const nodes = extraction.structural_nodes ?? [];
+  const ownerPaths = nodes.map((node) => node.owner_path);
+  const ownerSet = new Set(ownerPaths);
+  if (!unique(ownerPaths)) errors.push('structural_nodes.duplicate_owner_path');
+  const rootOwner = String(extraction.question_id).match(/_q([0-9]{2})$/)?.[1];
+  for (const node of nodes) {
+    const segments = String(node.owner_path).split('/');
+    const expectedParent = segments.length === 1 ? null : segments.slice(0, -1).join('/');
+    if (segments[0] !== `q${rootOwner}`) errors.push(`structural_nodes.${node.owner_path}.question_root`);
+    if (node.parent_owner_path !== expectedParent) errors.push(`structural_nodes.${node.owner_path}.parent_owner_path`);
+    if (expectedParent !== null && !ownerSet.has(expectedParent)) errors.push(`structural_nodes.${node.owner_path}.orphan_parent`);
+    if (node.whole_question_alias !== node.owner_path.endsWith('/$whole')) errors.push(`structural_nodes.${node.owner_path}.whole_question_alias`);
+  }
+  for (const node of nodes) {
+    const visited = new Set();
+    let cursor = node.owner_path;
+    while (cursor !== null) {
+      if (visited.has(cursor)) { errors.push(`structural_nodes.${node.owner_path}.cycle`); break; }
+      visited.add(cursor);
+      cursor = nodes.find((candidate) => candidate.owner_path === cursor)?.parent_owner_path ?? null;
+    }
+  }
+  const evidenceGroups = [
+    ['question.authoritative_regions', extraction.question?.authoritative_regions ?? [], 'qp'],
+    ...nodes.flatMap((node) => [
+      [`structural_nodes.${node.owner_path}.page_region_evidence`, node.page_region_evidence ?? [], 'qp'],
+      [`structural_nodes.${node.owner_path}.ms_evidence`, node.ms_evidence ?? [], 'ms'],
+    ]),
+  ];
+  const frozenEvidenceRows = evidenceManifest?.rows ?? [];
+  const expectedEvidenceManifestHash = evidenceManifest?.manifest_sha256;
+  if (!expectedEvidenceManifestHash || frozenEvidenceRows.length === 0) errors.push('evidence_manifest');
+  else {
+    const observedEvidenceManifestHash = sha256(Buffer.from(serialize({ schema_version: evidenceManifest.schema_version, rows: frozenEvidenceRows })));
+    if (observedEvidenceManifestHash !== expectedEvidenceManifestHash) errors.push('evidence_manifest.content_hash');
+    if (expectedEvidenceManifestHash !== extraction.question?.provenance?.page_chain_manifest_sha256) errors.push('evidence_manifest.hash_binding');
+  }
+  if (!Array.isArray(sourceRecords) || sourceRecords.length === 0) errors.push('source_authority');
+  else for (const [label, evidenceRows, documentType] of evidenceGroups) {
+    for (const evidence of evidenceRows) {
+      const source = sourceRecords.find((row) => row.source_object_id === evidence.source_object_id);
+      if (!source || source.document_type !== documentType || source.sha256 !== evidence.source_sha256 || !extraction.question?.source_membership?.includes(evidence.source_object_id)) errors.push(`${label}.source_binding`);
+      if (evidence.evidence_manifest_sha256 !== extraction.question?.provenance?.page_chain_manifest_sha256) errors.push(`${label}.manifest_binding`);
+      const frozenEvidence = frozenEvidenceRows.find((row) => row.source_object_id === evidence.source_object_id && row.page_number === evidence.page_number && row.region_id === evidence.region_id);
+      if (!frozenEvidence || ['source_sha256', 'page_image_sha256', 'crop_sha256'].some((field) => frozenEvidence[field] !== evidence[field])) errors.push(`${label}.frozen_evidence_binding`);
+      if (documentType === 'qp' && !extraction.question?.complete_page_chain?.includes(evidence.page_number)) errors.push(`${label}.page_binding`);
+    }
+  }
+  return errors;
+}
+
+export function validateCheckerPacket(packet, sourceRecords) {
+  const errors = [];
+  const expectedQuestionPrefix = `${String(packet.paper_id).replace(/^9709_/, 'qrow_9709_')}_q`;
+  const expectedSourceIds = {
+    qp: `srcdoc_${packet.paper_id}`,
+    ms: `srcdoc_${String(packet.paper_id).replace('_qp_', '_ms_')}`,
+  };
+  const pages = packet.complete_page_chain ?? [];
+  const pageNumbers = pages.map((row) => row.page_number);
+  const expectedExpression = `${packet.question_id}:pages:${pageNumbers.map((page) => String(page).padStart(3, '0')).join('+')}`;
+  if (!String(packet.question_id).startsWith(expectedQuestionPrefix)) errors.push('question_id');
+  if (packet.source_object_ids?.qp !== expectedSourceIds.qp || packet.source_object_ids?.ms !== expectedSourceIds.ms) errors.push('source_object_ids');
+  if (!Array.isArray(sourceRecords) || sourceRecords.length === 0) errors.push('source_authority');
+  else {
+    const qp = sourceRecords.find((row) => row.source_object_id === packet.source_object_ids?.qp);
+    const ms = sourceRecords.find((row) => row.source_object_id === packet.source_object_ids?.ms);
+    if (!qp || !ms || packet.source_hashes?.qp_sha256 !== qp.sha256 || packet.source_hashes?.ms_sha256 !== ms.sha256) errors.push('source_hashes');
+  }
+  if (pageNumbers.some((page, index) => index > 0 && page <= pageNumbers[index - 1])) errors.push('complete_page_chain');
+  if (packet.page_chain_expression !== expectedExpression) errors.push('page_chain_expression');
+  if (pages.some((row) => !String(row.image_path).endsWith(`/page-${String(row.page_number).padStart(3, '0')}.png`))) errors.push('complete_page_chain.image_path');
+  if (typeof packet.worker_id !== 'string' || !packet.worker_id.trim()) errors.push('worker_id');
+  if (typeof packet.shard_id !== 'string' || !packet.shard_id.trim()) errors.push('shard_id');
+  return errors;
+}
+
+export function assertPublishable(outputs) {
+  const validator = outputs?.[PATHS.validator];
+  if (validator?.status !== 'pass') {
+    const failed = validator?.checks?.filter((row) => row.status === 'fail').map((row) => row.id) ?? ['validator_result_missing'];
+    throw new Error(`validator failed: ${failed.join(', ')}`);
+  }
+}
